(function(){'use strict';
/* AI Agents Database generator — jahdb-ai-agents-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = Fact-checked public information */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-AGENTS-';
var SRC='public';
var RECORD_KIND='AI agents record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"brief":"An AI agent is a software system that perceives its environment, reasons about goals, and takes actions autonomously to achieve objectives - the fundamental unit of agentic AI.","examples":["A coding agent perceives a repository, plans a fix, writes code, runs tests, and iterates until the bug is resolved.","A travel agent books flights, hotels, and activities by calling booking APIs to satisfy a vacation request."],"history":["The term 'intelligent agent' comes from 1990s AI textbooks (Russell and Norvig); SHRDLU (1970) was an early language-driven agent.","AutoGPT's viral 2023 launch turned AI agents from academic topic into mainstream phenomenon."],"points":["The canonical agent loop is perceive-decide-act: observe the environment, choose an action, execute it, and observe the result.","Autonomy distinguishes agents from chatbots: agents pursue multi-step goals without step-by-step human direction.","Agents combine a reasoning engine (usually a large language model) with tools, memory, and an environment to act in.","The environment can be digital (APIs, browsers, code) or physical (robots, sensors) - the loop is the same.","Agency exists on a spectrum from scripted workflows to fully autonomous goal-pursuit; most production systems sit in between."],"qa":[["Agent vs chatbot?","A chatbot responds to prompts; an agent pursues goals through action loops, using tools and adapting to results."],["What makes an agent 'intelligent'?","Perception, reasoning about goals, acting, and learning from outcomes - the full loop, not just text generation."],["Do agents need LLMs?","Modern agents use LLMs as reasoning engines, but classical agents (thermostats, game AI) predate them."]],"title":"What Is an AI Agent","uses":["Software automation: agents handle multi-step digital tasks end to end.","Customer service: agents resolve inquiries using tools and knowledge bases.","Research: agents gather and synthesize information autonomously."]},{"title":"The Perception-Action Loop","brief":"The perception-action loop is the heartbeat of every agent: observe the environment, update beliefs, choose an action, execute, and repeat until the goal is reached.","points":["Perception converts raw environment data (API responses, page content, sensor readings) into a state representation the agent can reason about.","Decision-making selects actions using the LLM's reasoning over the current state, goal, and available tools.","Action execution calls tools or actuators, changing the environment and producing new observations.","The loop continues until a termination condition: goal achieved, max steps reached, or human intervention.","Loop design choices - observation format, action space, stopping rules - determine agent reliability more than model size."],"examples":["A web agent loops: screenshot page, decide click, click, screenshot result - until the form is submitted.","A data agent loops: query database, inspect results, refine query - until the analysis is complete."],"history":["The sense-plan-act loop comes from 1980s robotics (e.g., Shakey the robot).","ReAct (2022) formalized the interleaved reasoning-and-acting loop for LLM agents."],"uses":["Web automation agents navigating sites step by step.","DevOps agents diagnosing incidents through repeated probing.","Game agents playing via screen observation and input actions."],"qa":[["How many loop iterations do agents need?","Simple tasks take 3-10 steps; complex ones can run hundreds - hence max-step limits."],["What breaks the loop?","Unclear observations, unavailable actions, or the agent losing track of its goal."],["Can loops run forever?","Without termination conditions, yes - production agents always cap steps, time, or cost."]]},{"title":"Agent Architectures Overview","brief":"Agent architectures are the structural patterns organizing perception, reasoning, memory, and action - from simple loops to hierarchical teams.","points":["The ReAct architecture interleaves reasoning traces with tool actions in a single loop.","Plan-and-execute separates a planner (which decomposes goals) from executors (which carry out steps).","Reflexion-style architectures add self-critique loops that review and retry failed attempts.","Hierarchical architectures use manager agents that delegate to specialist sub-agents.","The choice depends on task complexity: simple loops for simple tasks, hierarchies for long-horizon missions."],"examples":["A research agent uses plan-and-execute: plan the report outline, then spawn sub-agents per section.","A coding agent uses ReAct: reason about the bug, run a test, observe, repeat."],"history":["Classical architectures (SOAR, ACT-R) modeled cognition in the 1980s-90s.","LLM-era architectures exploded after 2022: ReAct, Reflexion, AutoGPT, and hierarchical designs."],"uses":["Matching architecture to task complexity in production systems.","Research into which structures generalize best.","Teaching agent design as an engineering discipline."],"qa":[["Which architecture is best?","None universally - ReAct for interactive tasks, plan-and-execute for decomposable ones, hierarchies for complex missions."],["Can architectures combine?","Yes - hierarchical ReAct agents are common in production."],["Do I need a framework?","Frameworks implement these patterns so you configure rather than code them."]]},{"title":"The ReAct Pattern","brief":"ReAct (Reason + Act) prompts the agent to alternate between thinking out loud and taking actions, grounding reasoning in real observations.","points":["Each iteration produces a Thought (reasoning trace), then an Action (tool call), then an Observation (tool result).","The thought traces make agent behavior interpretable and debuggable - you see why it acted.","ReAct was introduced by Yao et al. in 2022 and became the default pattern for tool-using agents.","Variants add self-consistency (sampling multiple reasonings) or interleave planning steps.","The pattern works with any LLM and any tool set - it is a prompting discipline, not a model feature."],"examples":["HotpotQA question answering: the agent thinks about what to search, searches Wikipedia, reads results, and answers.","A support agent thinks through the customer's issue, queries the order system, and responds."],"history":["Yao et al. published 'ReAct: Synergizing Reasoning and Acting in Language Models' in late 2022.","ReAct became the template for LangChain agents and countless production systems."],"uses":["Question answering over tools and documents.","Customer support with backend system access.","Any task needing transparent, step-by-step tool use."],"qa":[["Why think out loud?","It grounds decisions in observations and creates an audit trail for debugging."],["Does ReAct waste tokens?","Thought traces cost tokens but dramatically improve reliability - usually worth it."],["ReAct vs chain-of-thought?","Chain-of-thought reasons once; ReAct reasons, acts, observes, and reasons again - closed loop."]]},{"title":"Tool Use and Function Calling","brief":"Tool use lets agents act on the world: calling APIs, running code, querying databases, and controlling software through defined interfaces.","points":["Function calling is the standard interface: the model emits structured calls, the runtime executes them and returns results.","Tools need clear schemas - name, description, parameters - because the agent only knows what the schema tells it.","Common tool categories: search, code execution, database queries, messaging, file operations, and domain APIs.","Tool design determines agent capability more than model choice: well-designed tools make agents powerful and safe.","Errors must be informative - agents recover from clear error messages but flounder on cryptic failures."],"examples":["A data agent calls a SQL tool to query sales figures, then a charting tool to visualize them.","An assistant books travel by calling flight, hotel, and calendar APIs in sequence."],"history":["Tool use emerged with WebGPT and code-executing models in 2021-2022.","OpenAI's function calling API (2023) standardized the interface; MCP (2024) standardized tool distribution."],"uses":["Enterprise automation: agents operating company systems through APIs.","Developer tools: agents running tests, linters, and deployments.","Personal productivity: agents managing email, calendars, and bookings."],"qa":[["How many tools can an agent handle?","Dozens with good descriptions; hundreds need retrieval or hierarchical organization."],["What makes a good tool?","Clear name, precise description, validated inputs, informative errors, and idempotent behavior."],["Can agents create their own tools?","Advanced agents write and save reusable tools - tool-making agents are an active research area."]]},{"title":"Planning and Task Decomposition","brief":"Planning lets agents break big goals into manageable steps, order them, and adapt the plan as execution unfolds.","points":["Decomposition turns 'plan a conference' into venue, catering, invitations, and schedule subtasks.","Classical planners (PDDL, search) guarantee correctness for formal domains; LLM planners handle open-ended tasks flexibly.","Plan-and-execute architectures separate planning from doing, letting each use the right model and strategy.","Replanning triggers on failure or new information - rigid plans break, adaptive plans survive.","Plan verification (checking steps against constraints before acting) prevents costly mistakes in the real world."],"examples":["A travel agent plans: flights first (constrained), then hotels near the venue, then activities.","A project agent decomposes a launch into 40 subtasks with dependencies and owners."],"history":["Classical AI planning (STRIPS, 1971) solved formal problems; LLM planning tackles messy real goals.","The 2023 agent boom made plan-and-execute a standard production pattern."],"uses":["Project management agents orchestrating complex workflows.","Logistics agents routing shipments with constraints.","Personal assistants planning multi-step life tasks."],"qa":[["Why do agents fail at planning?","Long-horizon dependencies, unclear subgoals, and no replanning on failure."],["LLM planning vs classical planning?","LLM planners are flexible but unreliable; classical planners are reliable but rigid - hybrids are emerging."],["How to improve agent planning?","Explicit plan representations, verification steps, and replanning triggers."]]},{"title":"Memory Systems for Agents","brief":"Agent memory gives continuity across steps and sessions: short-term context, working notes, and long-term stores the agent can retrieve.","points":["Short-term memory is the context window: recent observations and thoughts the model sees directly.","Working memory includes scratchpads and notes the agent writes to itself across steps.","Long-term memory uses vector databases or knowledge graphs to store and retrieve past experiences.","Episodic memory records what happened; semantic memory stores what was learned - both improve future performance.","Memory management (summarization, forgetting, consolidation) prevents context overflow on long tasks."],"examples":["A sales agent recalls past customer interactions from long-term memory to personalize outreach.","A coding agent summarizes a long debugging session into working notes to stay on track."],"history":["Memory-augmented networks (2016) and MemGPT (2023) pioneered explicit agent memory architectures.","Vector-database-backed memory became standard production practice."],"uses":["Personal assistants that remember user preferences across sessions.","Support agents with full customer history at hand.","Research agents accumulating knowledge across investigations."],"qa":[["How much can agents remember?","Context windows hold the recent past; vector stores hold effectively unlimited history with retrieval."],["Do agents learn permanently?","Only if experiences are written to long-term stores - otherwise each session starts fresh."],["What is MemGPT?","A 2023 system giving agents OS-like virtual memory management over infinite context."]]},{"title":"Multi-Agent Systems","brief":"Multi-agent systems coordinate groups of specialized agents - dividing labor, debating, and collaborating on problems no single agent handles well.","points":["Specialization beats generality: a researcher, a critic, and a writer collaborating outperform one do-everything agent.","Communication topologies range from centralized (manager delegates) to decentralized (peer negotiation).","Debate protocols have agents argue positions and converge, improving factuality on hard questions.","Coordination overhead is the main cost: more agents mean more messages, latency, and failure modes.","Game theory and mechanism design inform incentive structures for agent cooperation."],"examples":["A content team: researcher gathers facts, writer drafts, editor revises, fact-checker verifies.","Software team simulation: product manager, engineer, and QA agents building a feature together."],"history":["Multi-agent systems research dates to the 1980s (Minsky's Society of Mind, 1986).","The LLM era revived it: AutoGen (2023) made multi-agent apps buildable in an afternoon."],"uses":["Complex content production with specialized roles.","Software development teams of cooperating agents.","Simulation of markets, organizations, and social systems."],"qa":[["When do multiple agents help?","When tasks decompose into genuinely different skills - not for simple tasks where overhead dominates."],["How do agents communicate?","Structured messages, shared blackboards, or protocols like A2A - with full conversation logs."],["What goes wrong?","Coordination failures, infinite debate loops, and cascading errors between agents."]]},{"title":"LangChain","brief":"LangChain is the most widely used framework for building LLM applications and agents, providing chains, tools, memory, and orchestration primitives.","points":["Chains compose LLM calls, prompts, and tools into reusable sequences - the framework's core abstraction.","LangChain agents implement ReAct and plan-and-execute patterns with configurable tools and memory.","LangSmith adds observability: tracing, evaluation, and monitoring for production agent apps.","LangGraph (2024) adds stateful, cyclic workflows for complex multi-step agents.","The ecosystem includes 100+ integrations: vector stores, model providers, and tools."],"examples":["A startup builds a support agent in days using LangChain's agent executors and LangSmith tracing.","Researchers prototype retrieval agents with LangChain's document loaders and vector stores."],"history":["Harrison Chase launched LangChain in late 2022; it became the fastest-growing open-source AI project of 2023.","LangGraph's 2024 release addressed the need for stateful, looping agent workflows."],"uses":["Rapid prototyping of agent applications.","Production agents with LangSmith observability.","Education: the default framework taught for LLM app development."],"qa":[["LangChain vs raw API calls?","LangChain accelerates development but adds abstraction; simple apps may not need it."],["Is LangChain production-ready?","Yes with LangSmith observability, though teams should understand the abstractions they rely on."],["What is LangGraph?","LangChain's framework for stateful, cyclic agent workflows - agents as graphs, not chains."]]},{"title":"AutoGen","brief":"Microsoft's AutoGen is a framework for multi-agent applications, making it easy to build teams of conversing agents.","points":["Agents are conversable: they send and receive messages, with humans able to join the conversation.","Two-agent patterns (assistant + user-proxy) let agents execute code and report back autonomously.","Group chats orchestrate multiple specialists with a manager routing messages.","AutoGen Studio provides a no-code interface for building multi-agent apps.","The framework emphasizes code execution: agents write, run, and debug code as their primary action."],"examples":["A data-science team: analyst agent writes Python, executor runs it, critic reviews the charts.","An AutoGen group chat where coder, reviewer, and tester agents build a feature together."],"history":["Microsoft Research released AutoGen in 2023 (PyAutoGen); it quickly became the multi-agent standard.","AutoGen 0.2+ rebuilt the core for scalability and production use."],"uses":["Multi-agent software development teams.","Data analysis with cooperating specialist agents.","Research into agent conversation dynamics."],"qa":[["AutoGen vs LangChain?","AutoGen specializes in multi-agent conversation; LangChain covers broader LLM app patterns."],["Can humans join agent chats?","Yes - human-in-the-loop is a first-class pattern in AutoGen."],["Is AutoGen only for coding?","Code execution is its strength, but agents can use any tools."]]},{"title":"LangGraph","brief":"LangGraph models agents as stateful graphs with cycles, enabling complex looping workflows that linear chains cannot express.","points":["Nodes are computation steps (LLM calls, tool uses); edges route between them based on state.","Cycles allow loops: the agent can revisit planning after execution fails - impossible in linear chains.","State is shared across the graph, giving agents persistent memory of the workflow.","Human-in-the-loop interrupts pause the graph for approval at defined points.","LangGraph powers the most sophisticated LangChain agents: research assistants, coding teams, support systems."],"examples":["A support agent graph: classify, then loop through troubleshooting steps, escalating if unresolved.","A coding agent cycling between write, test, and debug nodes until tests pass."],"history":["LangChain introduced LangGraph in 2024 to address stateful agent needs.","It quickly became the recommended way to build complex agents in the ecosystem."],"uses":["Complex support and troubleshooting workflows.","Long-running research agents with persistent state.","Any agent needing loops, branching, and human checkpoints."],"qa":[["Graph vs chain?","Chains are linear; graphs support cycles, branching, and shared state - needed for real agents."],["Is LangGraph hard to learn?","More concepts than chains, but it matches how complex agents actually work."],["Can graphs call subgraphs?","Yes - hierarchical composition for multi-agent teams."]]},{"title":"Coding Agents","brief":"Coding agents perceive repositories, plan changes, write code, run tests, and iterate - automating software engineering tasks end to end.","points":["The loop: understand the issue, explore the repo, write a patch, run tests, fix failures, repeat.","SWE-bench measures real-world bug-fixing: top agents now resolve a large fraction of GitHub issues.","Tools include file search, code execution, test runners, and version control - the developer's toolkit.","Devin (Cognition, 2024) demonstrated end-to-end task completion; Copilot Workspace plans tasks from issues.","Challenges: long-horizon coherence, test-driven verification, and avoiding plausible-but-wrong patches."],"examples":["An agent fixes a reported bug: reproduces it, patches the code, and verifies with the test suite.","A migration agent updates a codebase to a new library version file by file."],"history":["Copilot (2021) autocompleted code; the agent leap came with SWE-bench (2023) and Devin (2024).","By 2025, coding agents were standard in professional development workflows."],"uses":["Bug fixing and test-driven development assistance.","Code migration and refactoring at scale.","Boilerplate generation and documentation."],"qa":[["Will coding agents replace developers?","They automate tasks, not judgment - developers become reviewers and architects."],["How are coding agents evaluated?","SWE-bench and similar: real issues, real tests, pass/fail - no partial credit."],["What limits them?","Long-horizon planning, understanding large codebases, and verifying correctness."]]},{"title":"Computer-Use Agents","brief":"Computer-use agents operate software through screens, keyboards, and mice like a human - the universal adapter for any application.","points":["The agent perceives screenshots (sometimes accessibility trees) and acts with clicks, keystrokes, and scrolls.","Anthropic's computer-use models (2024) and OpenAI's Operator (2025) brought the capability mainstream.","Grounding - mapping 'click the submit button' to screen coordinates - is the core technical challenge.","OSWorld and similar benchmarks measure real computer-task completion.","Safety is paramount: a computer-use agent can do anything a user can, including harmful actions."],"examples":["An agent fills out a expense report across three web apps by watching the screen.","Operator books a restaurant reservation by navigating the booking site like a person."],"history":["Early RPA bots were scripted; LLM computer-use (2024) made it general-purpose.","Anthropic's public computer-use release sparked the 2024-2025 wave."],"uses":["Automating legacy software with no API.","Testing applications by simulating real users.","Accessibility: operating computers for users who cannot."],"qa":[["Why not just use APIs?","Most software has no API - computer use works with everything, like a human temp worker."],["Are they reliable?","Improving fast, but UI changes and grounding errors still cause failures - human oversight remains standard."],["What are the risks?","Full computer control is dual-use; sandboxing and approval gates are essential."]]},{"title":"Research Agents","brief":"Research agents search, read, and synthesize information to produce reports - automating the gather-think-write cycle of knowledge work.","points":["The loop: plan research questions, search sources, read documents, extract findings, synthesize the report.","Deep Research systems (OpenAI, Google, 2025) produce cited, multi-page reports from a single prompt.","Source quality matters: agents must prefer primary sources and flag uncertain claims.","Citation is essential - research agents must show their work like human analysts.","Evaluation focuses on factuality, coverage, and source quality, not just fluency."],"examples":["A market analyst agent produces a 20-page competitive landscape with 50 cited sources.","A literature-review agent summarizes 100 papers on a topic with key findings extracted."],"history":["Early research agents (2023) were simple search-summarize loops.","Deep Research (2025) set the bar: long-horizon browsing with genuine synthesis."],"uses":["Market and competitive intelligence.","Academic literature reviews.","Due diligence and background research."],"qa":[["Can I trust agent research?","Verify citations - agents still hallucinate sources; the cited claims need checking."],["How long do they take?","Minutes to tens of minutes for deep reports - far faster than humans, slower than chat."],["What sources do they use?","The public web primarily; enterprise versions search internal documents."]]},{"title":"Customer Service Agents","brief":"Customer service agents handle inquiries end to end: understanding issues, checking systems, taking actions, and following up.","points":["The agent authenticates the customer, diagnoses the issue, and acts - refunds, rebookings, troubleshooting.","Integration with order systems, CRMs, and knowledge bases gives agents real capabilities, not just answers.","Escalation policies define when the agent hands off to humans: frustration, complexity, or value thresholds.","Tone and empathy are tuned for the brand; the agent represents the company.","Metrics shift from deflection to resolution: did the agent actually solve the problem?"],"examples":["An airline agent rebooks a cancelled flight, issues meal vouchers, and updates the passenger.","A telecom agent diagnoses a router issue by running remote line tests."],"history":["IVR phone trees and scripted chatbots were the old regime.","LLM agents (2023+) finally handle the long tail of real customer problems."],"uses":["E-commerce support: orders, returns, refunds.","Telecom and utilities: diagnostics and troubleshooting.","SaaS: technical support with product access."],"qa":[["Will agents replace support staff?","They handle routine volume; humans focus on complex, sensitive, high-value cases."],["How do agents avoid costly mistakes?","Approval gates for refunds, changes, and anything irreversible."],["What about angry customers?","Sentiment detection triggers human handoff before frustration boils over."]]},{"title":"Web-Browsing Agents","brief":"Web-browsing agents navigate the live internet: searching, reading pages, filling forms, and completing tasks across sites.","points":["Perception via page content, screenshots, or accessibility trees; action via clicks, typing, and navigation.","Search-then-read loops handle research; form-filling loops handle transactions.","CAPTCHAs, bot detection, and login walls are the practical adversaries of browsing agents.","Benchmarks like WebArena and Mind2Web measure real task completion on real sites.","Reliability comes from robust selectors, retry logic, and graceful degradation when pages change."],"examples":["A shopping agent compares prices across five retailers and buys the best deal.","A research agent reads 30 sources and compiles cited findings."],"history":["Early web agents were research demos; 2024-2025 made them consumer products.","Operator and similar agents brought browsing automation mainstream."],"uses":["Price comparison and purchase automation.","Lead generation and market research.","Testing websites by simulating user journeys."],"qa":[["Is agent browsing legal?","It must respect terms of service and robots.txt - unauthorized automation can violate them."],["How do agents handle logins?","Credential vaults and delegated auth - agents should never see raw passwords."],["What breaks browsing agents?","Site redesigns, bot detection, and multi-step flows with unclear states."]]},{"title":"Data Analysis Agents","brief":"Data analysis agents query data, run statistics, build visualizations, and explain findings - the analyst that never sleeps.","points":["The loop: understand the question, explore the data, run analyses, visualize, and narrate conclusions.","Code execution (Python/SQL) is the core tool; the agent writes and runs analysis code.","Julius AI, ChatGPT's Advanced Data Analysis, and similar products made this mainstream.","Trust requires showing work: code, queries, and assumptions must be inspectable.","The agent should flag uncertainty and avoid overclaiming from weak data."],"examples":["Upload a sales CSV; the agent finds the top drivers of churn with charts and a written summary.","A finance agent reconciles accounts and flags anomalies for review."],"history":["Code-executing chatbots (2023) evolved into full analysis agents.","2024-2025 products made agent analysis accessible to non-programmers."],"uses":["Business intelligence for teams without analysts.","Financial auditing and anomaly detection.","Scientific data exploration."],"qa":[["Can agents replace data analysts?","They automate routine analysis; analysts focus on framing questions and validating answers."],["How do I trust the results?","Inspect the code and queries - reputable agents show every step."],["What data is safe to upload?","Anonymize sensitive data; check the provider's data-use policies."]]},{"title":"Agent Evaluation and Benchmarks","brief":"Agent benchmarks measure what agents actually do: complete tasks, use tools correctly, and recover from failures - not just answer questions.","points":["SWE-bench: resolve real GitHub issues, verified by tests - the coding-agent standard.","GAIA: general assistant tasks requiring browsing, code, and reasoning.","WebArena: complete tasks on real websites in a controlled environment.","OSWorld: operate a real computer OS to finish tasks.","Good benchmarks test end-to-end success, tool-use accuracy, efficiency, and safety - not just final answers."],"examples":["A coding agent's SWE-bench score predicts its real bug-fixing ability.","An enterprise runs WebArena-style evals on its own internal tools before deploying agents."],"history":["2023-2024 saw an explosion of agent benchmarks as the field needed real measurement.","Benchmarks now drive the field like ImageNet drove vision."],"uses":["Comparing models and frameworks for agent tasks.","Pre-deployment validation of production agents.","Research into what makes agents reliable."],"qa":[["Why not just use chat benchmarks?","Chat benchmarks test answers; agents need testing on actions, tools, and multi-step success."],["Are benchmarks gamed?","Contamination and overfitting are real concerns - private held-out evals matter."],["What should I measure for my agent?","Task success rate, cost per task, latency, and failure modes on your own tasks."]]},{"title":"Agent Safety and Guardrails","brief":"Agent safety ensures autonomous systems act within bounds: constraining actions, verifying plans, and keeping humans in control.","points":["Action scoping: agents get only the tools and permissions they need - least privilege.","Plan verification: reviewing proposed action sequences before execution in high-stakes domains.","Approval gates: human confirmation for irreversible actions (payments, deletions, messages).","Monitoring and audit trails: every action logged for review and forensics.","Kill switches and rate limits bound the blast radius of misbehaving agents."],"examples":["A finance agent needs CFO approval for transfers over a threshold.","A deployment agent's plan is reviewed before it touches production."],"history":["Asimov's laws were fiction; real agent safety engineering emerged with production deployments in 2023-2025.","The field now has dedicated safety benchmarks and red-teaming practices."],"uses":["Enterprise deployments with compliance requirements.","Consumer agents handling money and personal data.","Any autonomous system with real-world effects."],"qa":[["What is the biggest agent safety risk?","Over-permissioned agents taking harmful actions - prompt injection plus broad tools."],["Are guardrails enough?","Defense in depth: scoping, verification, approvals, monitoring - no single layer suffices."],["Who is liable for agent mistakes?","Evolving law; currently the deployer - hence the emphasis on controls."]]},{"title":"Sandboxing Agents","brief":"Sandboxing isolates agents in controlled environments where mistakes are contained - the prerequisite for safe autonomous action.","points":["Code sandboxes: isolated containers for agent-written code with no network or filesystem access beyond what's needed.","Browser sandboxes: disposable profiles for web agents, reset after each task.","Permission models: capability-based access where agents hold explicit, revocable grants.","E2B, Modal, and cloud sandboxes provide infrastructure for safe agent execution.","The sandbox boundary is the security boundary - design it as carefully as any other."],"examples":["A coding agent runs untrusted generated code in a fresh container per task.","A web agent browses in an isolated profile with no access to the user's real sessions."],"history":["Software sandboxes are decades old; agent-specific sandboxing matured in 2023-2024.","E2B and similar services productized agent sandboxes."],"uses":["Running agent-generated code safely.","Isolating web agents from user data.","Testing agents before production deployment."],"qa":[["Is sandboxing enough for safety?","Necessary but not sufficient - combine with action scoping and monitoring."],["What can escape a sandbox?","Misconfigured permissions, unpatched vulnerabilities - treat sandboxes as one layer."],["Should every agent be sandboxed?","Every agent that executes code or touches the network - yes."]]},{"title":"Prompt Injection and Agents","brief":"Prompt injection is the top attack on agents: malicious instructions hidden in data the agent reads, hijacking its behavior.","points":["Direct injection: user input containing instructions the agent obeys as if from its operator.","Indirect injection: malicious instructions in web pages, documents, or tool outputs the agent processes.","Agents are especially vulnerable because they act on what they read - injected instructions become actions.","Defenses: input sanitization, instruction hierarchies (system > developer > user > tool), and output verification.","The field treats this as the fundamental unsolved security problem of agentic AI."],"examples":["A web page with hidden text instructing the browsing agent to exfiltrate data.","A document that tells the summarizing agent to ignore its safety rules."],"history":["Identified as a core LLM vulnerability in 2022; agent deployments made it critical in 2023-2025.","No complete defense exists - it remains an active research frontier."],"uses":["Red-teaming agent deployments for injection resistance.","Designing instruction hierarchies and trust boundaries.","Security evaluations for production agents."],"qa":[["Can prompt injection be fully fixed?","Not yet - it exploits the core ambiguity of language models following instructions in data."],["What helps most?","Treating tool outputs as untrusted data, never as instructions - plus human approval gates."],["Is my agent vulnerable?","If it reads untrusted content and takes actions, assume yes and design accordingly."]]},{"title":"Agent Identity and Authentication","brief":"As agents act on behalf of users and transact with each other, identity - who is this agent, and who authorized it - becomes critical infrastructure.","points":["Delegation: agents act with the user's authority, which must be scoped, revocable, and auditable.","Agent IDs and credentials distinguish agents from humans and from each other in logs and transactions.","OAuth-style flows let users grant agents limited permissions without sharing passwords.","Agent-to-agent authentication (via protocols like A2A) prevents impersonation in multi-agent systems.","Non-repudiation: cryptographic proof of which agent took which action, for accountability."],"examples":["A shopping agent checks out using a delegated payment credential scoped to $200.","Two enterprise agents authenticate mutually before sharing sensitive data."],"history":["Web auth (OAuth, 2012) solved human delegation; agent delegation standards are being built now.","2024-2025 protocol work made agent identity a first-class concern."],"uses":["E-commerce agents purchasing on behalf of users.","Enterprise agents accessing systems with scoped credentials.","Multi-agent systems with authenticated collaboration."],"qa":[["How do agents log in?","Through delegated credentials - tokens scoped to specific actions, never raw passwords."],["Can agents impersonate users?","Only with proper delegation; systems must distinguish agent actions from user actions in audit trails."],["What is agent spoofing?","An attacker posing as a legitimate agent - prevented by cryptographic identity."]]},{"title":"Long-Horizon Task Execution","brief":"Long-horizon tasks span hours or days of agent work: the frontier where current agents struggle most and improve fastest.","points":["The core challenge is coherence: maintaining goal focus across hundreds of steps without drift.","Strategies include explicit plans, periodic self-review, milestone checkpoints, and external memory.","Context management (summarization, selective forgetting) keeps long runs within window limits.","Evaluation is hard: success takes hours to verify, and partial credit is ambiguous.","Progress is rapid: each model generation extends the viable horizon significantly."],"examples":["An agent spending a day researching and writing a 50-page market report.","A coding agent working through a week-long migration across a large repo."],"history":["2023 agents managed minutes; 2024-2025 pushed to hours on structured tasks.","The horizon extends roughly with model capability generations."],"uses":["Deep research projects.","Large software migrations.","Extended monitoring and analysis tasks."],"qa":[["What breaks on long horizons?","Goal drift, context overflow, compounding errors, and unrecoverable failures."],["How to extend the horizon?","Better plans, checkpoints with human review, and robust error recovery."],["Will agents do week-long tasks?","Structured ones, increasingly - open-ended week-long autonomy remains aspirational."]]},{"title":"Agent Workflows vs Autonomous Agents","brief":"The industry distinguishes scripted agent workflows (predictable paths) from autonomous agents (open-ended pursuit) - choosing correctly is a key design decision.","points":["Workflows define the steps; the LLM handles individual steps - predictable, debuggable, reliable.","Autonomous agents choose their own steps toward a goal - flexible but unpredictable.","Anthropic's 2024 guidance: start with workflows, add autonomy only where needed.","Most production value comes from workflows; autonomy suits exploration and novel problems.","Hybrids route: workflow for the known path, autonomy for exceptions."],"examples":["A support workflow: classify, retrieve, draft, human-review - fixed steps, LLM-powered.","An autonomous researcher: given only a question, it plans and executes freely."],"history":["Early agent hype favored full autonomy; production experience (2024) swung back to workflows.","The distinction is now standard architecture guidance."],"uses":["Choosing the right autonomy level per task.","Explaining agent designs to stakeholders.","Evolving workflows toward autonomy incrementally."],"qa":[["Which should I build?","Workflows for known processes; autonomy for novel, variable tasks."],["Can workflows become agents?","Yes - add replanning and exception-handling autonomy to workflow steps gradually."],["Is autonomy the goal?","Reliability is the goal; autonomy is a means, used where it helps."]]},{"title":"Human-in-the-Loop Agents","brief":"Human-in-the-loop designs keep people in control at key points: approving actions, guiding plans, and handling exceptions.","points":["Approval gates: the agent proposes, the human disposes - for irreversible or high-stakes actions.","Plan review: humans approve the plan before execution begins.","Exception escalation: the agent works autonomously until stuck, then asks for help.","The loop should be ergonomic: batched approvals, clear diffs, one-click accept.","Over-reliance is the risk: humans rubber-stamping without real review."],"examples":["A finance agent batches 50 invoices for one-click approval.","A coding agent proposes a refactor plan; the developer approves before execution."],"history":["Human-in-the-loop is classical (aviation autopilots); agent frameworks made it a standard pattern.","LangGraph's interrupt feature productized approval checkpoints."],"uses":["Financial operations with human sign-off.","Code changes requiring review.","Any domain where mistakes are costly."],"qa":[["Doesn't this defeat autonomy?","No - it focuses autonomy where it's safe and keeps judgment where it matters."],["How to avoid rubber-stamping?","Meaningful review UI: diffs, risk flags, and sampled deep reviews."],["When can the human be removed?","When error rates and stakes justify it - measured, not assumed."]]},{"title":"Embodied Agents and Robotics","brief":"Embodied agents connect AI reasoning to physical bodies: perceiving through sensors and acting through motors in the real world.","points":["The loop extends to physics: vision, touch, and proprioception in; motor commands out.","Foundation models for robotics (RT-2, OpenVLA) bring language understanding to robot control.","Simulation-to-real transfer trains in virtual worlds before deploying to physical robots.","The hardest problems are physical: grasping, dexterity, and unpredictable environments.","Safety is physical: a wrong action breaks things or hurts people - constraints are mandatory."],"examples":["A warehouse robot picks varied items from bins using vision-language guidance.","A home robot prototype folds laundry through learned dexterous policies."],"history":["Classical robotics (1980s-2010s) was programmed; learning-based control took over in the 2010s.","LLM-robotics fusion (2023+) brought general reasoning to physical agents."],"uses":["Warehouse and logistics automation.","Manufacturing with flexible robots.","Assistive robotics for elder care."],"qa":[["When will home robots arrive?","Narrow tasks are here; general home robots remain years away."],["Why is robotics harder than chat?","Physics: the real world is unforgiving, and data is far scarcer than text."],["Are robots agents?","Yes - the full perceive-reason-act loop, with physical consequences."]]},{"title":"Scientific Discovery Agents","brief":"Discovery agents design experiments, analyze results, and propose hypotheses - accelerating the scientific method itself.","points":["The loop: hypothesize, design experiment, execute (in lab automation or simulation), analyze, repeat.","Notable systems have discovered new materials, optimized reactions, and found novel drug candidates.","Agents excel at searching large hypothesis spaces humans can't fully explore.","Human scientists remain essential for framing questions and judging significance.","Reproducibility is enforced: agents log every step for independent verification."],"examples":["A materials agent discovered new battery electrolytes by searching chemical space.","A drug-discovery agent proposed candidates later validated in wet labs."],"history":["Robot scientists (Adam, 2009) automated yeast genetics; LLM agents (2023+) generalized the approach.","2024-2025 saw discovery agents across chemistry, biology, and physics."],"uses":["Materials and drug discovery.","Experimental optimization in chemistry and biology.","Literature-driven hypothesis generation."],"qa":[["Will agents replace scientists?","They accelerate discovery; scientists still frame questions and interpret meaning."],["How are discoveries verified?","Through physical experiments and independent replication - agents propose, reality disposes."],["What are the risks?","Dual-use: discovery agents could aid harmful research - hence screening and oversight."]]},{"title":"The Model Context Protocol (MCP)","brief":"MCP is Anthropic's open standard for connecting agents to tools and data - USB-C for AI integrations.","points":["MCP defines servers (exposing tools, resources, prompts) and clients (agents using them).","One MCP server works with any MCP client - write the integration once.","Servers exist for databases, file systems, APIs, and enterprise systems - a growing ecosystem.","Security model: explicit user consent for tool access, scoped permissions.","Anthropic open-sourced MCP in late 2024; rapid adoption made it the de facto tool standard."],"examples":["A Postgres MCP server gives any agent safe database access.","An enterprise exposes internal APIs as MCP servers for all its agents."],"history":["Anthropic released MCP in November 2024 as an open standard.","2025 saw explosive server ecosystem growth."],"uses":["Standardized tool distribution for agent builders.","Enterprise integration: expose systems once, use from any agent.","Agent marketplaces built on interoperable tools."],"qa":[["MCP vs function calling?","Function calling is per-model API; MCP is the distribution standard for tools across models."],["Is MCP secure?","Its consent and scoping model is sound; server implementations must be vetted like any software."],["Who maintains MCP?","Anthropic stewards it as an open standard with community contributions."]]},{"title":"Agent-to-Agent Protocol (A2A)","brief":"Google's A2A protocol standardizes how agents communicate: discovering each other, delegating tasks, and exchanging results.","points":["Agent Cards advertise capabilities: what an agent can do, in machine-readable form.","Tasks are the unit of delegation: one agent assigns work to another with context and requirements.","The protocol handles authentication, status updates, and result delivery.","A2A complements MCP: MCP connects agents to tools, A2A connects agents to agents.","Launched by Google in 2025 with broad industry backing."],"examples":["A travel agent delegates hotel booking to a specialist agent via A2A.","Enterprise agents from different vendors collaborate on a supply chain task."],"history":["Google announced A2A in April 2025 with 50+ launch partners.","It filled the gap MCP left: standardized agent-to-agent messaging."],"uses":["Cross-vendor agent collaboration.","Agent marketplaces with standardized hiring.","Enterprise agent ecosystems."],"qa":[["A2A vs MCP?","Complementary: MCP for tools, A2A for agent-to-agent communication."],["Do I need both?","If your agents use tools and collaborate, yes - they solve different problems."],["Is A2A open?","Yes - an open standard with broad industry participation."]]},{"title":"History of AI Agents","brief":"From SHRDLU's blocks world to today's autonomous systems, the agent idea has driven AI for over fifty years.","points":["1970: SHRDLU understood language about a blocks world - the first language-driven agent.","1980s-90s: intelligent agents became the field's organizing concept (Russell & Norvig's textbook).","1997-2019: game agents (Deep Blue, AlphaGo, AlphaStar) proved the techniques at superhuman levels.","2022-2023: LLMs made general-purpose agents possible; AutoGPT went viral.","2024-2025: protocols (MCP, A2A) and products made agents mainstream infrastructure."],"examples":["SHRDLU moving blocks per typed commands - primitive but recognizably agentic.","The 2023 AutoGPT boom: thousands experimenting with autonomous agents overnight."],"history":["Each era's agents reflected its AI: symbolic, then learning-based, now language-model-driven.","The throughline: perceiving, reasoning, and acting toward goals."],"uses":["Understanding where agent ideas came from.","Avoiding reinvented wheels - classical agent research solved many problems.","Teaching the field's foundations."],"qa":[["What's genuinely new now?","Language understanding as the universal interface - agents that work with any software described in words."],["What did old agents get right?","Architectures, planning formalisms, and multi-agent coordination - still relevant."],["Will history repeat?","The hype cycles rhyme; the capabilities compound."]]},{"title":"Agent Regulation and Policy","brief":"Governments are beginning to regulate AI agents: liability, disclosure, and safety requirements for autonomous systems.","points":["The EU AI Act classifies some agentic systems as high-risk, requiring conformity assessments.","Key issues: liability for agent actions, disclosure when interacting with AI, and safety testing.","Sectoral rules apply: finance, healthcare, and legal agents face existing professional regulations.","The US approach is sectoral and evolving; states are experimenting with agent-specific rules.","Industry self-governance (safety frameworks, red-teaming standards) runs ahead of law."],"examples":["A financial agent must meet the same compliance standards as a human advisor.","Deployed agents in the EU document their capabilities and limitations for high-risk uses."],"history":["AI regulation focused on models until agents made deployment the issue (2024-2025).","The policy conversation shifted from 'what can models do' to 'what may agents do'."],"qa":[["Who is liable when an agent errs?","Generally the deployer - maintain controls and insurance accordingly."],["Must agents identify as AI?","Increasingly yes, especially in sensitive contexts - check your jurisdiction."],["How to prepare?","Document capabilities, implement safety controls, and monitor regulatory developments."]],"uses":["Compliance teams design agent controls that satisfy emerging regulatory requirements.","Product teams assess whether their agents trigger high-risk classifications under new laws.","Policymakers study deployed agent incidents to ground future regulation in real evidence."]},{"title":"Agent Testing and Simulation","brief":"Testing agents requires simulation: sandboxed environments where agents practice tasks safely before touching production.","points":["Simulation environments mirror production: same tools, fake data, no real consequences.","Test suites cover happy paths, edge cases, adversarial inputs, and failure recovery.","Replay testing re-runs recorded scenarios against new agent versions for regression detection.","Fuzzing generates random task variations to find brittleness.","Simulation is also training: agents improve by practicing in realistic sandboxes."],"examples":["A shopping agent tested against a simulated store with 10,000 products before going live.","A support agent handling 1,000 simulated angry customers to tune escalation."],"history":["Software testing practices adapted to agents in 2023-2024.","Agent-specific testing frameworks emerged with the first production deployments."],"uses":["Pre-deployment validation of agent behavior.","Regression testing across agent versions.","Training agents in safe simulated worlds."],"qa":[["How is agent testing different?","Non-determinism: the same test can pass or fail - statistical testing over many runs."],["What coverage is enough?","Cover your top tasks deeply, plus adversarial and failure cases - then monitor production."],["Can simulation fully validate?","No - production always surprises; simulation plus gradual rollout is the practice."]]},{"title":"Agent Cost Optimization","brief":"Agent costs come from model tokens, tool calls, and compute time - optimizing them is essential for viable deployments.","points":["Token costs dominate: each loop iteration burns prompt + completion tokens across all steps.","Strategies: smaller models for simple steps, caching repeated calls, and concise prompts.","Tool-call costs (APIs, searches) often exceed model costs - batch and cache aggressively.","Measure cost per successful task, not per call - failed loops are pure waste.","The frontier: capability per dollar improves yearly as models get cheaper and more efficient."],"examples":["Routing simple classifications to a small model cut an agent's cost 80%.","Caching tool results eliminated redundant API calls across loop iterations."],"history":["2023 agents were prohibitively expensive for many uses; 2024-2025 cost collapses opened production.","Cost engineering became a standard agent discipline."],"uses":["Making agent deployments economically viable.","Pricing agent-powered products.","Choosing models per subtask by cost-capability tradeoff."],"qa":[["What drives agent cost most?","Long loops with big models - shorten loops and right-size models."],["How to estimate before building?","Prototype, measure tokens and calls per task, then project at scale."],["Will costs keep falling?","Yes - model efficiency trends strongly favor cheaper capable agents."]]},{"title":"Agent Latency Engineering","brief":"Agent latency - the time from request to completed task - determines whether agents feel magical or broken.","points":["Latency sources: model inference per step, tool calls, and sequential dependencies between steps.","Parallelize independent subtasks; stream partial results so users see progress.","Smaller, faster models for latency-critical steps; big models only where needed.","Speculative execution starts likely next steps before confirmation.","Set expectations: show the plan and progress, not a spinner."],"examples":["A research agent streams findings section by section instead of one long wait.","Parallel sub-agents cut a 10-minute task to 3 minutes."],"history":["Early agents took minutes per task; engineering brought common tasks to seconds.","Real-time voice agents pushed latency under a second end to end."],"uses":["Consumer agents where responsiveness drives adoption.","Voice and chat interfaces with strict latency budgets.","High-throughput automation pipelines."],"qa":[["What's an acceptable latency?","Seconds for chat, minutes for deep tasks - with visible progress throughout."],["Speed vs quality?","Right-size per step: fast models for routine steps, strong models for hard ones."],["How to measure?","Time to first useful output and time to task completion - both matter."]]},{"title":"Multi-Modal Agents","brief":"Multi-modal agents perceive and act across text, images, audio, and video - handling the full richness of digital environments.","points":["Vision lets agents read screenshots, diagrams, and photos - essential for computer use and real-world tasks.","Audio enables voice interaction and sound understanding.","Video understanding supports surveillance, content review, and tutorial following.","Cross-modal reasoning connects what the agent sees with what it reads and hears.","The frontier: agents that fluidly combine modalities like humans do."],"examples":["An agent watches a repair video, reads the manual, and guides the fix.","A shopping agent compares products by image, reviews by text, and specs by table."],"history":["Vision-language models (2023) gave agents eyes; video and audio followed.","2024-2025 multi-modal agents became standard."],"uses":["Computer-use agents navigating visual interfaces.","Content moderation across media types.","Accessibility: describing the visual world."],"qa":[["Do multi-modal agents cost more?","Yes - image and video tokens are expensive; use vision where it adds value."],["When is vision essential?","UIs, diagrams, photos, video - anywhere text alone loses information."],["What's hardest?","Video reasoning over long durations and precise spatial understanding."]]},{"title":"Agent Security Architecture","brief":"Agent security architecture treats agents as privileged insiders: powerful, semi-trusted, and needing layered controls.","points":["Threat model: prompt injection, tool abuse, data exfiltration, and privilege escalation.","Trust boundaries: separate system instructions from user input from tool output - never confuse them.","Least privilege: each agent gets minimal tools, data, and permissions for its task.","Monitoring: anomaly detection on agent actions catches compromises in progress.","Incident response: kill switches, credential revocation, and forensic trace analysis."],"examples":["A compromised browsing agent is contained by its sandbox before reaching internal systems.","Anomaly detection flags an agent exfiltrating data via encoded tool calls."],"history":["Agent security emerged as a discipline with production deployments in 2023-2025.","Red-teaming practices and security benchmarks developed rapidly."],"uses":["Designing safe enterprise agent deployments.","Security reviews of agent architectures.","Compliance with emerging AI security standards."],"qa":[["What's the top threat?","Prompt injection leading to tool abuse - the classic agent attack chain."],["How to bound the damage?","Sandboxing, least privilege, and approval gates - defense in depth."],["Are agents insiders or outsiders?","Treat them as semi-trusted insiders: useful, powerful, and requiring oversight."]]},{"title":"Personal Data Agents","brief":"Personal data agents manage your information across services: finding, organizing, and acting on your digital life.","points":["The agent needs access to email, files, calendars, and accounts - the keys to your digital kingdom.","Privacy architecture: local processing where possible, encrypted storage, minimal retention.","Data portability: agents help you move, export, and understand your own data.","The fiduciary framing: the agent should act solely in your interest, like a doctor or lawyer.","Regulation (GDPR, etc.) gives users rights agents must respect: access, deletion, portability."],"examples":["An agent finds every subscription you're paying for and cancels the unused ones.","A move-assistant updates your address across dozens of services."],"history":["Personal data management was manual; agents (2024+) automate the digital housekeeping.","Fiduciary AI is an emerging design philosophy."],"uses":["Subscription and account management.","Digital decluttering and organization.","Privacy audits: what do companies hold on you?"],"qa":[["Can I trust an agent with everything?","Only with strong privacy architecture and the ability to audit and revoke."],["What is fiduciary AI?","Agents legally and ethically bound to act in the user's best interest."],["How do I take my data back?","Agents should support full export and deletion - verify before granting access."]]},{"title":"Enterprise Agent Platforms","brief":"Enterprise agent platforms provide the governed infrastructure for building, deploying, and managing agents at organizational scale.","points":["Core services: identity, permissions, audit logging, cost tracking, and model management.","Platforms from Microsoft (Copilot Studio), Google, Salesforce, and ServiceNow embed agents in business workflows.","Build-vs-buy: platforms accelerate standard use cases; custom builds suit unique needs.","Governance features: approval workflows, data-loss prevention, and compliance reporting.","The platform choice shapes what agents can do - evaluate integration depth with your systems."],"examples":["A bank deploys service agents on its platform with full audit trails for regulators.","HR onboarding agents run on the company platform with role-based permissions."],"history":["RPA platforms (2010s) automated scripts; agent platforms (2024+) automate reasoning.","The shift from RPA to AI agents is the enterprise automation story of the decade."],"uses":["Standardizing agent development across the enterprise.","Governed deployment with compliance built in.","Scaling from pilot agents to production fleets."],"qa":[["Platform vs framework?","Platforms add governance, hosting, and integrations; frameworks are building blocks."],["How to choose?","Integration with your systems, governance features, and total cost."],["Will platforms lock us in?","Somewhat - prefer open standards (MCP, A2A) to preserve flexibility."]]},{"title":"Open-Source Agent Frameworks","brief":"Open-source frameworks power much of agent innovation: transparent, hackable, and free from vendor lock-in.","points":["Leading projects: LangChain/LangGraph, AutoGen, CrewAI, Semantic Kernel, and emerging challengers.","Advantages: transparency, community, customization, and no per-seat costs.","Tradeoffs: self-hosting burden, variable documentation, and faster-moving APIs.","The ecosystem moves fast: today's best practice may be legacy next quarter.","Contributing back builds the commons every agent developer relies on."],"examples":["Startups building entire products on LangGraph without licensing costs.","Researchers extending AutoGen for novel multi-agent experiments."],"history":["Open source drove the 2023 agent boom; frameworks competed on GitHub stars.","Maturation brought governance, security practices, and enterprise support options."],"uses":["Startups avoiding platform costs.","Research requiring full transparency.","Custom agent architectures vendors don't offer."],"qa":[["Open source vs commercial?","Open for control and cost; commercial for support and integrated governance."],["Is open source secure?","Transparency helps; vet dependencies and keep frameworks updated."],["Which license?","Check carefully - some 'open' agent projects have restrictive commercial terms."]]},{"title":"Agent UX Design","brief":"Agent UX design shapes how humans collaborate with agents: trust, control, and clarity in every interaction.","points":["Show the plan: users trust agents that explain what they'll do before doing it.","Progress visibility: streaming updates beat silent waiting.","Control points: easy approval, editing, and stopping - the user stays in charge.","Error handling: clear explanations and recovery options, not cryptic failures.","Calibrated trust: the UI should convey uncertainty, not false confidence."],"examples":["A coding agent shows its plan as a checklist, checking items off as it works.","A travel agent presents options with tradeoffs instead of booking blindly."],"history":["Chat UX (2022) gave way to agentic UX patterns in 2024-2025.","Design systems for agents are now emerging."],"uses":["Consumer agent products where trust drives adoption.","Enterprise tools where operators supervise agents.","Any interface where humans and agents collaborate."],"qa":[["How much should agents explain?","Plans and key decisions always; every micro-step only on demand."],["What builds trust?","Reliability first, then transparency - a transparent but wrong agent loses trust fast."],["Should agents have personalities?","Light personality aids rapport; heavy persona distracts from the task."]]},{"title":"Failure Modes of Agents","brief":"Agents fail in characteristic ways: loops, hallucinations, tool errors, goal drift, and prompt injection - knowing the taxonomy speeds diagnosis.","points":["Looping: repeating the same action - caused by uninformative observations or missing termination.","Hallucinated tools: calling functions that don't exist or with invented parameters.","Goal drift: losing the original objective over long runs.","Tool errors: cascading failures from one bad tool result.","Prompt injection: malicious instructions hijacking behavior - the security failure mode."],"examples":["An agent stuck refreshing a page 50 times - classic looping from unchanged observations.","A booking agent drifting from 'cheapest flight' to 'nicest hotel' over 30 steps."],"history":["Each failure mode was discovered in production and named by practitioners.","Mitigation patterns are now standard engineering knowledge."],"uses":["Faster debugging via failure-mode recognition.","Designing agents that avoid known failure patterns.","Building monitors that detect failures early."],"qa":[["Which failure is most common?","Looping and tool errors in development; goal drift on long production runs."],["Can failures be eliminated?","No - but recognized, monitored, and mitigated systematically."],["How to detect drift?","Periodic goal-restatement checks and outcome validation against the original request."]]},{"title":"Tool Design for Agents","brief":"Well-designed tools make agents capable; poorly designed ones make them fail - tool design is agent design.","points":["Schemas are the UI: clear names, descriptions, and parameters teach the agent what the tool does.","Granularity: tools should match task steps - not too fine (chatty) or too coarse (inflexible).","Idempotency: safe retries require tools that tolerate repeated calls.","Error messages should guide: 'user not found, check the ID format' beats 'error 400'.","Versioning: tools evolve; agents need stable contracts or graceful adaptation."],"examples":["A search tool returning snippets plus source URLs - exactly what a research agent needs.","A booking tool with dry-run mode lets agents verify before committing."],"history":["API design principles adapted to agent consumers in 2023-2024.","MCP standardized how tools are described and discovered."],"uses":["Building internal tools for enterprise agents.","Designing public APIs that agents use well.","Evaluating third-party tools for agent compatibility."],"qa":[["What makes a tool agent-friendly?","Clear schema, helpful errors, idempotency, and predictable behavior."],["How many parameters?","Few, well-documented ones - agents struggle with sprawling parameter lists."],["Should tools be chatty?","Return what's needed plus pointers to more - let the agent pull details."]]},{"title":"Collaborative Agents with Humans","brief":"The most productive pattern isn't autonomous or manual - it's collaborative: humans and agents each doing what they do best.","points":["Division of labor: agents handle scale, speed, and recall; humans handle judgment, creativity, and accountability.","Mixed-initiative interaction: either party can take the lead as the task evolves.","The agent as thought partner: critiquing, suggesting, and drafting while the human decides.","Trust calibration: the collaboration works when each party knows the other's strengths and limits.","The future of work is human-agent teams, not humans versus agents."],"examples":["A writer and agent co-authoring: agent drafts and researches, human shapes and decides.","A doctor and diagnostic agent: agent surfaces possibilities, doctor diagnoses."],"history":["Mixed-initiative systems research (1990s-2000s) laid the groundwork.","LLM copilots (2023+) made human-agent collaboration mainstream."],"uses":["Knowledge work: writing, analysis, design.","Professional services: law, medicine, consulting.","Creative collaboration: brainstorming and iteration."],"qa":[["Will collaboration replace jobs?","It transforms them: practitioners become editors, directors, and validators."],["How to design the handoff?","Clear ownership per subtask, with smooth escalation in both directions."],["What do humans uniquely add?","Judgment, accountability, taste, and responsibility - the things that matter most."]]},{"title":"Agent Governance","brief":"Agent governance is the organizational discipline of managing agent fleets: who can deploy what, with what permissions, under what oversight.","points":["Registries: every production agent registered with owner, purpose, permissions, and risk tier.","Change management: agent updates go through testing and approval like software releases.","Access reviews: periodic audits of what each agent can touch.","Incident processes: defined playbooks for agent misbehavior.","The goal: innovation speed with safety - governance as enabler, not blocker."],"examples":["A bank's agent registry tracks 200 production agents with quarterly access reviews.","An incident playbook isolates a misbehaving agent in minutes."],"history":["IT governance adapted to agents in 2024-2025 as fleets grew.","Regulatory pressure accelerated governance adoption."],"uses":["Enterprises scaling from pilots to agent fleets.","Regulated industries needing demonstrable control.","Any organization where agents touch important systems."],"qa":[["Isn't governance bureaucracy?","Good governance is lightweight guardrails; bad governance is bureaucracy - design for the former."],["What should be governed?","Permissions, data access, deployment changes, and incidents - the risk surface."],["Who owns agent governance?","Jointly: engineering, security, compliance, and business owners."]]},{"title":"Agents in Healthcare","brief":"Healthcare agents assist clinicians and patients: triage, documentation, care coordination, and patient engagement - under strict safety requirements.","points":["Clinical documentation agents draft notes from encounters, reducing physician burnout.","Triage agents assess symptoms and route patients to appropriate care levels.","Care-coordination agents schedule follow-ups, manage referrals, and track adherence.","Regulatory bar is high: HIPAA, FDA considerations, and clinical validation.","The principle: agents assist clinicians; licensed professionals make medical decisions."],"examples":["An agent drafts the visit note while the doctor talks to the patient.","A post-discharge agent checks on patients and flags concerns to nurses."],"history":["Medical chatbots were limited; LLM agents (2023+) handle real clinical workflows.","Health systems now deploy agents with clinical oversight."],"uses":["Reducing clinician documentation burden.","Patient engagement and follow-up.","Prior authorization and administrative automation."],"qa":[["Can agents diagnose?","They can assist differential diagnosis; diagnosis remains the clinician's responsibility."],["What about liability?","Healthcare agent liability is evolving - maintain human oversight and documentation."],["Are patients comfortable?","For administrative tasks, yes; for clinical judgment, most want human clinicians."]]},{"title":"Agents in Finance","brief":"Finance agents handle analysis, compliance, customer service, and operations - in one of the most regulated agent environments.","points":["Research agents analyze filings, earnings, and markets for investment teams.","Compliance agents monitor transactions and flag suspicious activity.","Customer-service agents handle account inquiries with strict authentication.","Risk management: every agent action needs audit trails and limits.","Regulations (SEC, FINRA, banking rules) shape every financial agent design."],"examples":["An analyst agent builds a comp table from 50 filings overnight.","A compliance agent reviews communications for regulatory violations."],"history":["Algorithmic trading pioneered financial agents; LLM agents (2023+) handle language-heavy finance work.","Banks now run governed agent fleets."],"uses":["Investment research and analysis.","Regulatory compliance monitoring.","Customer service and operations."],"qa":[["Can agents trade autonomously?","With strict limits and oversight - fully autonomous trading faces steep regulatory hurdles."],["What records are required?","Complete audit trails of agent actions, like any financial system."],["How is advice regulated?","Financial advice from agents faces the same rules as human advisors."]]},{"title":"Agents in Education","brief":"Education agents tutor, grade, and personalize learning - scaling one-on-one attention that was previously impossible.","points":["Tutoring agents adapt to each student's pace, knowledge gaps, and learning style.","The best tutors use Socratic methods: guiding discovery rather than giving answers.","Grading agents handle routine assessment; teachers focus on complex evaluation.","Concerns: academic integrity, over-reliance, and equitable access.","Evidence is promising: well-designed tutoring agents measurably improve learning."],"examples":["A math tutor that diagnoses misconceptions and targets them with practice.","A writing coach giving instant feedback on drafts."],"history":["Intelligent tutoring systems (1980s-2010s) were narrow; LLM tutors (2023+) handle any subject.","Schools and universities are adopting with evolving policies."],"uses":["Personalized tutoring at scale.","Teacher assistance: grading, planning, feedback.","Lifelong learning and professional training."],"qa":[["Will agents replace teachers?","No - they amplify teachers, handling routine work while teachers mentor and inspire."],["What about cheating?","Assessment design must evolve; agents are tools, and policies are catching up."],["Do they actually help learning?","Well-designed tutoring shows real gains; passive answer-giving does not."]]},{"title":"Small Model Agents","brief":"Small-model agents run capable agents on modest hardware: phones, laptops, and edge devices - bringing agency everywhere.","points":["Small models (1-8B parameters) handle many agent steps: classification, extraction, simple tool use.","Strategies: small models for routine steps, big models for hard reasoning - the cascade pattern.","Fine-tuning small models for specific agent roles beats generic big models on cost.","On-device agents preserve privacy: data never leaves the phone.","The trend: capability per parameter rises, pushing more agency to the edge."],"examples":["A phone agent handling messages and calendar entirely on-device.","An edge agent monitoring factory equipment without cloud dependence."],"history":["Early agents needed frontier models; efficient small models (2024-2025) changed the economics.","On-device AI became a platform priority."],"uses":["Privacy-sensitive personal agents.","Offline and low-connectivity environments.","Cost-sensitive high-volume automation."],"qa":[["Are small models capable enough?","For bounded tasks, yes - especially fine-tuned for the role."],["When do I need big models?","Novel reasoning, complex planning, and open-ended tasks."],["Will edge agents grow?","Rapidly - the economics and privacy advantages are compelling."]]},{"title":"The Path to AGI Agents","brief":"Many researchers see autonomous agents as the path to artificial general intelligence: systems that can do any cognitive task, end to end.","points":["The thesis: agency - pursuing goals in the world - is the missing ingredient beyond language modeling.","Milestones: longer horizons, better planning, reliable tool use, and open-ended learning.","Skeptics note: current agents are brittle outside their training distribution.","Safety scales with capability: more capable agents need stronger governance.","The timeline is debated; the direction - toward more capable agents - is not."],"examples":["Each generation extends the viable task horizon: minutes to hours to days.","Open-ended learning agents that improve from experience point toward generality."],"history":["AGI discussion is decades old; agents made it concrete - generality you can demo.","2023-2025 agent progress intensified the debate."],"uses":["Orienting research toward the capabilities that matter.","Calibrating investment and policy to plausible trajectories.","Distinguishing hype from real progress."],"qa":[["Are agents AGI?","No - but increasingly capable agents are the clearest visible path toward it."],["What would convince skeptics?","Reliable week-long autonomy on novel tasks would change minds."],["Should we slow down?","The governance debate: capability growth versus safety readiness."]]},{"title":"Future of Autonomous Agents","brief":"The trajectory points toward ubiquitous capable agents: personal superintelligence, agent economies, and transformed work - with governance racing to keep up.","points":["Personal agents: everyone with a capable digital chief of staff within years.","Agent economies: agents hiring agents, with protocols, payments, and reputations.","Work transformation: humans directing agent workforces rather than doing routine tasks.","Scientific acceleration: agent researchers compressing discovery timelines.","The central challenge: keeping agency aligned with human flourishing as capabilities grow."],"examples":["A 2030 morning: your agent negotiated, scheduled, researched, and drafted before you woke.","Agent marketplaces where specialized agents sell their services."],"history":["Every prediction here extrapolates 2023-2025 trends; the specifics will surprise us.","The pattern of past technology waves: transformation bigger than predicted, different in detail."],"uses":["Strategic planning for the agentic transition.","Policy design for an agent-populated economy.","Career and education preparation."],"qa":[["How fast will this happen?","Faster than institutions expect, slower than demos suggest - the usual pattern."],["What should I do now?","Learn to direct agents; build agent literacy in your organization."],["Optimistic or worried?","Both: the potential is enormous, and so is the need for thoughtful governance."]]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief,genre:angle,type:RECORD_KIND,content:content, content_completeness:'stub',
    stub_note:'Topic stub: the topic title and its one-line brief are real; the full guide article is not yet written. This record does not present shell text as a complete guide.',demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-ai-agents-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('ai-agents',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();